function updateDuel(p){const d=world.duel,visible=mode==='chaos'&&!!d&&['duel','duel_prep'].includes(world.phase);$('duelPanel').hidden=!visible;$('watchDuel').hidden=!visible;if(!visible)return;const ids=d.ids,key=ids.join(':')+':'+ids.map(id=>world.players[id].abilities.map(s=>s.id+':'+s.rank)).join('|');if(betKey!==key){betKey=key;$('duelCompetitors').replaceChildren();$('betTarget').replaceChildren();for(const id of ids){const a=world.players[id],card=el('div','duel-card'),copy=el('div');card.append(heroPortrait(a.hero,100,90));copy.append(el('strong','',`${a.name} / ${heroName(a.hero)}`),el('small','',`Ур. ${a.level} · побед ${a.duelWins} · ${number(a.gold+a.spent)} G стоимость`),el('small','',a.abilities.map(s=>CHAOS_SKILL_BY_ID[s.id].name).join(' · ')));card.append(copy);$('duelCompetitors').append(card);const opt=el('option','',a.name);opt.value=id;$('betTarget').append(opt);}}
 const prep=world.phase==='duel_prep',bet=world.bets[seat],participant=ids.includes(seat),pool=Object.values(world.bets).reduce((n,b)=>n+b.amount,0);$('duelTitle').textContent=prep?'СЛЕДУЮЩАЯ ДУЭЛЬ':'ДУЭЛЬ ИДЁТ';$('duelCountdown').textContent=prep?`До боя ${Math.max(0,Math.ceil(world.phaseTime))}с`:`${Math.floor(world.phaseTime)} / 50с`;$('betControls').hidden=!prep||!p||participant||!!bet||p.eliminated;$('betAmount').max=Math.floor((p?.gold||0)/2);$('betStatus').textContent=`Банк: ${number(pool)} G. `+(participant?'Ты участвуешь: ставки на свой бой запрещены. КД сохраняются, HP/MP восстанавливаются. Жизни за дуэль не снимаются.':bet?`Твоя ставка: ${bet.amount} G на ${playerName(bet.target)}.`:prep?'Одна ставка за бой, до половины золота. Победители делят общий банк пропорционально ставке. Ничья возвращает ставки.':'Ставки закрыты.');}
function updateStandings(){const body=$('standings');body.replaceChildren();for(const p of Object.values(world.players).sort((a,b)=>mode==='pudge'?a.team-b.team||b.kills-a.kills:b.lives-a.lives||b.duelWins-a.duelWins||b.gold+b.spent-a.gold-a.spent)){const tr=el('tr',`${p.id===seat?'me ':''}${p.eliminated?'out':''}`),name=el('td'),r=roster.find(r=>r.id===p.id);name.append(el('strong','',p.name+(p.id===seat?' · ТЫ':'')),el('small','',`${heroName(p.hero)} · ${net?(r?.human?'онлайн':'бот'):p.id===seat?'ты':'бот'}`));tr.append(name);for(const value of [mode==='pudge'?p.team===0?'Radiant':'Dire':`${'♥'.repeat(p.lives)}${p.eliminated?'Выбыл':''}`,p.level,`${p.kills} / ${p.deaths} / ${p.assists}`,p.creepKills||0,`${p.duelWins}–${p.duelLosses}`,p.clearedWaves,number(p.damageDealt),number(p.healing),number(p.gold+p.spent)+' G'])tr.append(el('td','',String(value)));tr.title='Нажми, чтобы наблюдать';tr.onclick=()=>{watch=p.id;view='focus';$('watchSeat').value=watch;};body.append(tr);}}
function updateUI(){if(!initialized||!world)return;const p=me(),online=!!net,locked=!!invited&&!online;$('connection').textContent=net?net.socket?.readyState===WebSocket.OPEN?`● ВМЕСТЕ · ${net.ping} MS`:'◌ ПЕРЕПОДКЛЮЧЕНИЕ':`● ЛОКАЛЬНО · ${fps} FPS`;$('createRoom').hidden=online||locked;$('joinRoom').hidden=online;$('codeLabel').hidden=online;$('copyInvite').hidden=!online;$('leaveRoom').hidden=!online;$('playerName').disabled=seat==='host'&&online;$('seat').disabled=online&&!net.host;$('scoreLimit').disabled=online||world.started;$('startMatch').hidden=world.started||world.gameOver||locked||online&&!net.host;$('startMatch').textContent=online?'Начать матч →':world.wave>0?'Продолжить с ботами →':'Играть с ботами →';$('restartMatch').hidden=!world.gameOver||online&&!net.host;$('roomBadge').textContent=online?`🔒 ${mode==='pudge'?'Pudge Wars':'Custom Hero Chaos'} · комната ${net.code} · ${net.host?'ты ведущий':'запускает ведущий'}`:locked?'🔒 Режим закреплён приглашением':'Свободные места занимают боты';if(online)$('lobbyHint').textContent=net.host?'Режим комнаты закреплён. Друзья входят по приглашению; только ты запускаешь матч. Свободные места играют боты. Можно занять любое свободное место.':'Ты вошёл по приглашению. Только ведущий запускает матч. Переподключение сохраняет героя, умения и место.';
 $('heroDraft').hidden=mode!=='chaos'||!p||!!p.hero||world.started||locked;$('heroReroll').disabled=!!p?.heroRerolled;$('abilityDraft').hidden=mode!=='chaos'||!p?.offer.length||locked;buildHeroes(p);buildDraft(p);buildSkillBar(p);updateShop(p);if(mode==='pudge')updateHook(p);updateDuel(p);
 const wk=Object.keys(world.players).map(id=>id+world.players[id].name+world.players[id].hero).join();if(watchKey!==wk){watchKey=wk;$('watchSeat').replaceChildren();for(const a of Object.values(world.players)){const o=el('option','',`${a.name} / ${heroName(a.hero)}`);o.value=a.id;$('watchSeat').append(o);}$('watchSeat').value=watch;}
 $('matchClock').textContent=clock(world.seconds);const phase=world.phase;let state=mode==='pudge'?`${world.score[0]} : ${world.score[1]}  /  ${world.targetScore}`:`ВОЛНА ${world.wave||1}`;if(!world.started)state='ПОДГОТОВКА МАТЧА';else if(world.gameOver)state=mode==='pudge'?`ПОБЕДА ${world.winner===0?'RADIANT':'DIRE'}`:`ПОБЕДИТЕЛЬ: ${playerName(world.winner)}`;else if(phase==='duel')state='ДУЭЛЬ';else if(phase==='duel_prep')state=`ДУЭЛЬ ЧЕРЕЗ ${Math.max(0,Math.ceil(world.phaseTime))}С`;else if(phase==='prep')state=`СЛЕДУЮЩАЯ ВОЛНА ЧЕРЕЗ ${Math.max(0,Math.ceil(world.phaseTime))}С`;$('matchState').textContent=state;$('waveTraits').textContent=mode==='chaos'&&world.started&&phase==='wave'?`${world.wave%10===0?'Древний':world.wave%4===0?'Магическая защита':world.wave%4===2?'Бронированные':'Смешанная волна'} · ${Math.max(0,Math.ceil(chaosWaveRules(world.wave).duration-world.phaseTime))}с`:mode==='pudge'?'Первое касание цепляет · союзник получает 0 урона':'';
 $('identity').textContent=p?`${p.name.toUpperCase()} / ${heroName(p.hero).toUpperCase()}`:'♛ ВЕДУЩИЙ / НАБЛЮДАТЕЛЬ';$('progress').textContent=p?`Ур. ${p.level} · ${mode==='pudge'?`хук ${p.hookHits}/${p.hooksThrown}`:`${p.lives}/5 жизней · ${p.points} очков · ${Math.round(arcadeAttack(world,p))} ATK · ${arcadeAttackRate(world,p).toFixed(1)}/с`}`:'Свободные герои играют сами';const max=p?arcadeMaxHP(world,p):1,mp=p?arcadeMaxMana(world,p):1;$('hpFill').style.width=`${Math.max(0,(p?.hp||0)/max*100)}%`;$('mpFill').style.width=`${Math.max(0,(p?.mana||0)/mp*100)}%`;$('hpLabel').textContent=p?`${Math.ceil(p.hp)} / ${max} HP${p.shield>0?' + '+Math.ceil(p.shield)+' щит':''}`:'Наблюдение';$('mpLabel').textContent=p?`${Math.ceil(p.mana)} / ${mp} MP`:'';$('goldLabel').textContent=`${number(p?.gold)} G`;$('autoFire').textContent=`Автоогонь: ${auto?'вкл. (в прицел)':'выкл.'}`;$('autoFire').setAttribute('aria-pressed',String(auto));$('pauseLocal').hidden=online;$('pauseLocal').textContent=paused?'Продолжить':'Пауза';$('arenaNotice').textContent=world.gameOver?state:!world.started?(locked?'Сначала займи место в комнате':p&&!p.hero?'Выбери одного из четырёх героев выше':p&&!p.abilities.length&&mode==='chaos'?'Выбери первую способность выше':online&&!net.host?'Ждём, когда ведущий начнёт матч':'Готово. Можно начинать матч'):paused?'ПАУЗА':p?.eliminated?'Ты выбыл. Наблюдай за оставшимися героями.':p?.respawn>0?`Возрождение через ${Math.ceil(p.respawn)}с`:p?.failedRound&&phase==='wave'?'Волна проиграна · −1 жизнь. Следующая попытка в новом раунде.':p?.cleared&&phase==='wave'?'Волна пройдена. Можно закупиться и улучшить умения.':p?.channel?`${CHAOS_SKILL_BY_ID[p.channel.skill]?.name||p.channel.kind} · ${p.channelLeft.toFixed(1)}с · движение прервёт подготовку`:world.duel&&phase==='duel'&&!world.duel.ids.includes(seat)?'Дуэль идёт. Нажми «Смотреть дуэль».':'';updateStandings();resizeParent();}
function processEvents(){for(const e of world.events||[]){if(e.id<=lastEvent)continue;lastEvent=e.id;if(['damage','impact','burst','lightning','cast','beam'].includes(e.type)){effects.push({...e,born:performance.now()/1000,life:e.type==='damage'?.7:e.type==='lightning'?.25:.45});if(effects.length>180)effects.shift();}let text='';switch(e.type){case 'wave':text=`Волна ${e.wave}: ${e.kind==='magic_resist'?'магическая защита':e.kind==='armored'?'броня':'смешанные нейтралы'}`;break;case 'wave_failed':text=`${playerName(e.player)}: −1 жизнь, осталось ${e.lives}`;break;case 'wave_clear':if(e.player===seat)text=`Волна пройдена за ${e.seconds}с · +${e.gold} G`;break;case 'duel_announced':text=`Дуэль: ${e.players.map(playerName).join(' против ')}`;break;case 'duel_end':text=`Дуэль: ${e.winner?playerName(e.winner)+' победил':'ничья'} · банк ${e.pot} G`;break;case 'kill':text=`${playerName(e.killer)} → ${playerName(e.player)} · ${e.score.join(':')}`;break;case 'rescue':text=`${playerName(e.player)} спас союзника`;break;case 'rune':text=`${playerName(e.player)} забрал руну ${e.kind}`;break;case 'match_end':text=mode==='pudge'?`Победила команда ${e.winner===0?'Radiant':'Dire'}`:`Последний выживший: ${playerName(e.winner)}`;break;case 'learn':if(e.player===seat)text=`Изучено: ${CHAOS_SKILL_BY_ID[e.skill]?.name}`;break;case 'catchup':if(e.player===seat)text='Догоняющая замена: выбери новое умение бесплатно';break;}if(text){eventLog.unshift({text,at:clock(world.seconds)});eventLog=eventLog.slice(0,12);}}$('eventLog').replaceChildren(...eventLog.map(e=>{const li=el('li');li.append(el('time','',e.at),document.createTextNode(e.text));return li;}));}
function aimAt(){const p=me();return aim||{x:p?.aimX||900,y:p?.aimY||500};}
function cast(skill){dispatch({type:'cast',skill,...aimAt()});}
function shoot(){if(!world.started||world.gameOver||paused)return;dispatch({type:mode==='pudge'?'hook':'attack',...aimAt()},{quiet:true});}
function pointer(e){const r=canvas.getBoundingClientRect(),cam=arcadeCamera(world,watch,view);aim={x:((e.clientX-r.left)*1800/r.width-cam.ox)/cam.scale,y:((e.clientY-r.top)*1000/r.height-cam.oy)/cam.scale};}
canvas.addEventListener('pointermove',e=>pointer(e));canvas.addEventListener('pointerdown',e=>{pointer(e);if(e.button===2){dispatch({type:'move',...aim});}else if(e.button===0){held=e.pointerType!=='touch';shoot();}canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointerup',()=>held=false);canvas.addEventListener('pointercancel',()=>held=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('pointerup',()=>held=false);
function typing(e){return /INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||$('helpDialog').open;}
window.addEventListener('keydown',e=>{if(typing(e)||!initialized)return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k===' '){shoot();return;}if(k==='p'&&!net){paused=!paused;updateUI();return;}if(mode==='pudge'){if(k==='q')shoot();if(k==='b')dispatch({type:'item',item:'shield',...aimAt()});if(k==='e')dispatch({type:'item',item:'blink',...aimAt()});return;}if(k==='b'||k==='m')dispatch({type:'item',item:k==='b'?'bkb':'mjollnir',...aimAt()});const index=skillKeys.indexOf(k),p=me();if(index>=0&&p?.abilities[index])cast(p.abilities[index].id);if(k==='z'&&p?.invoked[0])cast(p.invoked[0].id);if(k==='c'&&p?.invoked[1])cast(p.invoked[1].id);if(k==='v'&&p?.stolen)cast(p.stolen.id);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();held=false;if(world?.started&&me())dispatch({type:'walk',dx:0,dy:0},{quiet:true});lastMove='0,0';});
let touchMove=null;for(const b of document.querySelectorAll('[data-walk]')){b.onpointerdown=e=>{e.preventDefault();touchMove=b.dataset.walk.split(',').map(Number);b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>touchMove=null;}
function controls(dt){actionClock+=dt;if(actionClock<.1)return;actionClock=0;const p=me();if(!p||!world.started||world.gameOver||paused||typing({target:document.activeElement}))return;let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(touchMove)[x,y]=touchMove;const key=x+','+y;if(x||y||key!==lastMove&&!p.channel){dispatch({type:'walk',dx:x,dy:y},{quiet:true});lastMove=key;}if(held||keys.has(' ')||auto)shoot();}
function frame(time){const dt=Math.max(0,Math.min(.05,(time-last)/1000||0));last=time;frameCount++;if(time-fpsAt>1000){fps=Math.round(frameCount*1000/(time-fpsAt));frameCount=0;fpsAt=time;}if(initialized&&world){controls(dt);if(!net&&!paused&&!document.hidden&&!invited){stepArcade(world,dt,arcadeSlots(mode).filter(id=>id!==seat));processEvents();}let renderWorld=net?(motion.sample(time)||world):world;if(net&&me()){const predicted=prediction.sample(world,me(),dt,net.ping);renderWorld={...renderWorld,players:{...renderWorld.players,[seat]:predicted}};}effects=effects.filter(e=>time/1000-e.born<e.life);drawArcadeScene(ctx,renderWorld,{seat,watch,view,aim,time:time/1000,effects});uiClock+=dt;saveClock+=dt;if(uiClock>.2){updateUI();uiClock=0;}if(saveClock>4){save();saveClock=0;}}requestAnimationFrame(frame);}
function resizeParent(){if(window.parent!==window)window.parent.postMessage({type:'oscar-arcade-height',height:Math.ceil(document.querySelector('.arcade-shell').getBoundingClientRect().height)+8},'*');}
function buildHelp(){$('helpContent').replaceChildren();const paragraphs=mode==='pudge'?[
'Pudge Wars: две команды по пять, река непроходима пешком. Бросай хук через реку, цепляй первое тело, вытаскивай противников и спасай своих. Хук летит и возвращается физически: можно увернуться и перехватить его союзником.',
'WASD / стрелки — движение; ПКМ — идти в точку. ЛКМ, Space или Q — хук в прицел. Хук наносит урон, для убийства нужны повторные попадания. После смерти возрождение через 4 секунды, ограничений жизней нет. Побеждает команда, первой набравшая заданный счёт.',
'Попадания и убийства дают опыт и золото. Очки уровней или золото улучшают урон, дальность, скорость и ширину хука. Руны в реке можно вытащить хуком. B — Hook Guard (если куплен), E — Blink на текущем берегу. Хук союзника не наносит урон.',
]:[
'Custom Hero Chaos: 8 отдельных арен, 5 жизней каждому. Выбери одного из 4 случайных героев. Один бесплатный переброс сохраняет первого и меняет остальных трёх. Включены 24 интересных героя, их основные наборы, 10 призываемых заклинаний Invoker и исторические дополнения Tinker.',
'Выбери одно умение из 16 предложений. Каждая родная способность имеет вес ×4 относительно одного чужого умения. Это наше значение вероятности, а не заявленный шанс оригинальной кастомки. Следующие слоты открываются после волн 1, 3, 5, 8. Обычно 5 слотов; шестой стоит 13 000 G. Очки уровней улучшают изученные умения. Ранги ультов 2/3 требуют уровни 6/12.',
'WASD / стрелки / ПКМ — ходить. ЛКМ или Space — бесплатная атака в прицел. Q E R F G T — слоты умений. У каждого активного умения своя мана и КД. Прямые снаряды не доворачивают. Для направленных на юнита заклинаний держи прицел прямо на нём. Движение прерывает подготовку и каналы.',
'После каждых двух волн проходит дуэль двух игроков. 15 секунд на подготовку и ставку: участники не ставят, остальные могут поставить до половины текущего золота. HP/MP дуэлянтов полные, но КД сохраняются. Дуэль длится до смерти или 50 секунд; затем сравниваются доли HP. Дуэль не отнимает PVE-жизнь. Победители ставок пропорционально делят общий банк, при ничьей деньги возвращаются.',
'На волне у каждого свои крипы: магия и атаки не пересекаются между личными аренами. За скорость зачистки дают бонус золота. Каждая десятая волна — древний с охраной. На бронированных и устойчивых к магии волнах меняй тактику. Просроченная волна тоже отнимает жизнь. Выживший последним выигрывает матч.',
'Смешивай связки: Rearm обновляет обычные заклинания, Multicast повторяет базовую магию, Metamorphosis меняет иллюзии, Sunder обменивает HP, Rubick копирует последний скилл врага в V. Invoker: изученные Quas/Wex/Exort собирают три сферы, Invoke создаёт умение в Z/C. Его 10 заклинаний также выпадают отдельно. Tether и Infest требуют собственного призванного юнита — без него они бесполезны.',
'Лавка: шесть предметов, активные BKB (B) и Mjollnir (M), Maelstrom улучшается за разницу. Токен 1200 G меняет случайный скилл, 2900 G — выбранный, новый навык сохраняет ранг в пределах своего максимума. Отстающие иногда получают бесплатную замену. Scepter/Shard используют общие усиления нашей арены, а не все варианты улучшений оригинальной Dota.',
];for(const text of [...paragraphs,'Онлайн: запусти npm run online, открой адрес localhost и нажми «Создать комнату в этом режиме». Скопируй приглашение. Друзьям ничего скачивать не нужно. Режим закреплён на сервере; только ведущий запускает и перезапускает матч. Свободные места занимают боты. Ведущий может играть или наблюдать. Компьютер и терминал ведущего должны оставаться включёнными.','Локально игра не требует сети. Прогресс сохраняется отдельно для каждого режима. Незавершённая волна после перезагрузки разыгрывается заново; жизни и покупки сохраняются. P — локальная пауза. Во время онлайна общая игра не ставится на паузу.','Это адаптация для браузера с узнаваемыми основными механиками, а не точная реализация актуального движка Dota 2: без всех фасетов, врождённых талантов и частных Aghanim-взаимодействий.'])$('helpContent').append(el('p','',text));}
